fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    // Since the problem guarantees a non-empty list, `len` > 0.
    // Compute rotation offset k = n mod len
    let k = n % len;
    // s is the split point: we take the suffix starting at s, then the prefix up to s
    let s = len - k;

    // Pre-allocate output with the same length
    let mut new_list = Vec::with_capacity(len);

    // Append the suffix from s..len
    new_list.extend_from_slice(&list[s..]);
    // Append the prefix from 0..s
    new_list.extend_from_slice(&list[..s]);

    new_list
}

